import { InjectionToken } from '@angular/core';
// Generated by scripts/extract-card-data.mjs from the legacy data files (npm runs it before build, start and test)
import generatedCardData from '../../generated/card-data.json';
import { CardImageTables } from './card-blueprint';

/**
 * The card image tables. Their source stays in the legacy client's files (`PC_Cards.js`, `hobbit.js`, `set40.js`,
 * `cards/CardImages.js`, `cards/PackImages.js`), so adding a card image still means editing only those; the build
 * turns them into JSON. card-data.parity.spec.ts checks the JSON is what those files define.
 */
export const CARD_IMAGE_TABLES = new InjectionToken<CardImageTables>('CARD_IMAGE_TABLES', {
  providedIn: 'root',
  factory: () => generatedCardData,
});
